// Durable Gradle pin.
//
// The Android Gradle wrapper MUST stay at 8.14.3 — Gradle 9 breaks the React Native
// Gradle plugin with an `IBM_SEMERU` error. The android/ folder is gitignored and gets
// regenerated by `expo prebuild`, which would otherwise reset the wrapper to the Expo
// SDK default. This script re-asserts the pin and is wired into `postinstall`,
// `prebuild`, and the `android` build script so the pin survives regeneration.
//
// Idempotent and safe: it never throws (always exits 0) and no-ops when the wrapper
// file doesn't exist yet (e.g. a managed project before the first prebuild).
const fs = require("fs");
const path = require("path");

const REQUIRED = "8.14.3";
const file = path.join(__dirname, "..", "android", "gradle", "wrapper", "gradle-wrapper.properties");

try {
  if (!fs.existsSync(file)) {
    console.log("[pin-gradle] no android wrapper yet — skipping (will run again after prebuild).");
    process.exit(0);
  }
  const desiredLine = `distributionUrl=https\\://services.gradle.org/distributions/gradle-${REQUIRED}-bin.zip`;
  const txt = fs.readFileSync(file, "utf8");
  const re = /^distributionUrl=.*$/m;
  if (!re.test(txt)) {
    console.warn("[pin-gradle] distributionUrl line not found — leaving the file untouched.");
    process.exit(0);
  }
  const current = txt.match(re)[0];
  if (current === desiredLine) {
    console.log(`[pin-gradle] OK — Gradle wrapper already pinned to ${REQUIRED}.`);
    process.exit(0);
  }
  fs.writeFileSync(file, txt.replace(re, desiredLine));
  console.log(`[pin-gradle] re-pinned Gradle to ${REQUIRED} (was: ${current.replace("distributionUrl=", "")}).`);
  process.exit(0);
} catch (e) {
  // Never break install/build because of the pin helper.
  console.warn("[pin-gradle] skipped:", e && e.message ? e.message : e);
  process.exit(0);
}
